//! Reading a vocabulary pack and turning text into vectors.
//!
//! The format is documented in `docs/paquetes-de-vocabulario.md` and
//! generated by `tools/construir_paquete.py`. This module is the only part
//! of the binary that knows a tokenizer or a quantization exists.

use anyhow::{bail, Context, Result};
use memmap2::Mmap;
use sha2::{Digest, Sha256};
use std::path::Path;
use tokenizers::Tokenizer;

const MARCA: &[u8; 4] = b"ANPK";
const VERSION: u32 = 1;

#[derive(Debug)]
pub struct Pack {
    mapping: Mmap,
    tok: Tokenizer,
    name: String,
    dims: usize,
    n_tokens: usize,
    scales: Vec<f32>,
    mins: Vec<f32>,
    table_start: usize,
}

/// Takes `n` bytes starting at `*o`, advances `*o` and returns the slice.
///
/// It uses `checked_add` because `n` almost always comes from a length field
/// read raw from the file: in a corrupt pack it can be any value up to 64
/// bits, and adding it straight to `*o` would overflow the pointer
/// arithmetic (with overflow-checks, the default for `cargo test`, that
/// panics instead of returning an error). An overflow and a merely truncated
/// file end in the same `Err`, naming the file and the field.
fn take_bytes<'a>(m: &'a [u8], o: &mut usize, n: usize, pack_path: &Path, campo: &str) -> Result<&'a [u8]> {
    let fin = o
        .checked_add(n)
        .filter(|&fin| fin <= m.len())
        .with_context(|| {
            format!("pack {} ends before it declared: {campo} is missing", pack_path.display())
        })?;
    let s = &m[*o..fin];
    *o = fin;
    Ok(s)
}

fn u32_en(m: &[u8], o: &mut usize, pack_path: &Path, campo: &str) -> Result<u32> {
    let f = take_bytes(m, o, 4, pack_path, campo)?;
    Ok(u32::from_le_bytes(f.try_into().unwrap()))
}

fn u64_en(m: &[u8], o: &mut usize, pack_path: &Path, campo: &str) -> Result<u64> {
    let f = take_bytes(m, o, 8, pack_path, campo)?;
    Ok(u64::from_le_bytes(f.try_into().unwrap()))
}

fn f32s_en(m: &[u8], o: &mut usize, n: usize, pack_path: &Path, campo: &str) -> Result<Vec<f32>> {
    let largo = n.checked_mul(4).with_context(|| {
        format!("pack {} declares a {campo} that is too large", pack_path.display())
    })?;
    let f = take_bytes(m, o, largo, pack_path, campo)?;
    Ok(f.chunks_exact(4).map(|c| f32::from_le_bytes(c.try_into().unwrap())).collect())
}

/// The longest name a pack may declare. Real ones are `en-es`; the cap is
/// there so a name cannot be a payload in its own right.
const MAX_NAME: usize = 64;

/// Rejects a declared name that is not a plain file name.
///
/// The name is not a label: `packstore::pack_path` builds
/// `paquetes/{name}.anathem-pack` out of it, and `Path::join` neither
/// neutralises `..` nor refuses an absolute path — it replaces the base
/// with it. A pack declaring `../../../../home/alguien/.bashrc` would have
/// `install` deposit its own bytes there, `reconcile` rename over it, and
/// `remove` delete whatever lives at that path. The bytes of the pack are
/// the attacker's, so that is arbitrary code execution at the next shell.
///
/// It is checked here, where the name is first read from the file, so no
/// `Pack` can ever exist carrying one that is not a plain file name, and
/// every path that builds a route out of `p.name()` inherits the guarantee
/// without repeating the check.
///
/// Both separators are rejected on every platform, not only the local one:
/// a pack built on Linux gets installed on Windows, and a name that is one
/// component here can be two there. `:` goes with them for the same reason
/// — `C:evil` is an ordinary name on Unix and a drive-relative path on
/// Windows.
pub fn validate_name(name: &str) -> Result<(), String> {
    if name.is_empty() {
        return Err("is empty".into());
    }
    if name.chars().count() > MAX_NAME {
        return Err(format!("is longer than {MAX_NAME} characters"));
    }
    if name == "." || name == ".." {
        return Err(format!("is «{name}», which names a directory and not a file"));
    }
    if name.starts_with('.') {
        return Err("starts with a dot".into());
    }
    if let Some(c) = name.chars().find(|&c| c == '/' || c == '\\' || c == ':') {
        return Err(format!("contains «{c}», which separates path components"));
    }
    if let Some(c) = name.chars().find(|c| c.is_control()) {
        return Err(format!("contains the control character U+{:04X}", c as u32));
    }
    // Belt and braces against anything the explicit checks above do not
    // name: whatever the platform makes of these bytes, it has to come out
    // as exactly one ordinary component.
    let mut comps = Path::new(name).components();
    match (comps.next(), comps.next()) {
        (Some(std::path::Component::Normal(c)), None) if c == name => Ok(()),
        _ => Err("is not a plain file name".into()),
    }
}

impl Pack {
    /// Opens and validates a pack. It does **not** verify the sha256: doing
    /// so on every startup would mean hashing tens of megabytes and would
    /// penalise whoever does not even use the vector layer. The sha is
    /// verified once, on install (see `mem model install`).
    pub fn open_pack(pack_path: &Path) -> Result<Pack> {
        let file = std::fs::File::open(pack_path)
            .with_context(|| format!("could not open the pack {}", pack_path.display()))?;
        let mapping = unsafe { Mmap::map(&file)? };
        if mapping.len() < 20 || &mapping[0..4] != MARCA {
            bail!("{} is not an anathem pack: the ANPK marker is missing", pack_path.display());
        }
        let mut o = 4usize;
        let version = u32_en(&mapping, &mut o, pack_path, "version")?;
        if version != VERSION {
            bail!(
                "pack {} declares version {version} and this binary understands {VERSION}",
                pack_path.display()
            );
        }
        let dims = u32_en(&mapping, &mut o, pack_path, "dimensions")? as usize;
        let n_tokens = u32_en(&mapping, &mut o, pack_path, "token count")? as usize;
        let name_len = u32_en(&mapping, &mut o, pack_path, "name length")? as usize;
        if dims == 0 || n_tokens == 0 {
            bail!("pack {} declares 0 dimensions or 0 tokens", pack_path.display());
        }
        let name_bytes = take_bytes(&mapping, &mut o, name_len, pack_path, "name")?;
        let name = std::str::from_utf8(name_bytes)
            .with_context(|| format!("the name of pack {} is not valid UTF-8", pack_path.display()))?
            .to_string();
        // Before anything else that costs: the name becomes a filesystem
        // path downstream, so a hostile one is refused here and never
        // reaches a `Pack`. See `validate_name`.
        if let Err(por_que) = validate_name(&name) {
            bail!(
                "the name that pack {} declares {por_que}; a pack names its own file, \
                 so it has to be a plain file name",
                pack_path.display()
            );
        }
        let tok_len = u64_en(&mapping, &mut o, pack_path, "tokenizer length")? as usize;
        // Everything the rest of the header commits the file to, added up
        // and compared against what the file actually measures, **before**
        // handing the tokenizer's bytes to `tokenizers` and its C regex
        // engine. A pack that is evidently malformed — a truncated table, a
        // length that overflows — should never reach that parser, which is
        // by far the largest surface this format exposes.
        //
        // `saturating_mul` and not `checked_mul`: a product that saturates
        // to `usize::MAX` fails the comparison against what is left of the
        // file just the same, and the error then names the field that is
        // out of range instead of a generic overflow.
        let restante = mapping.len() - o; // take_bytes garantiza o <= len
        let mut necesario = 0usize;
        for (campo, n) in [
            ("the tokenizer", tok_len),
            ("the scales", dims.saturating_mul(4)),
            ("the minimums", dims.saturating_mul(4)),
            ("the table", n_tokens.saturating_mul(dims)),
        ] {
            necesario = necesario
                .checked_add(n)
                .filter(|&t| t <= restante)
                .with_context(|| {
                    format!(
                        "pack {} is truncated: it declares a size for {campo} that the file \
                         does not cover, and {restante} bytes remain",
                        pack_path.display()
                    )
                })?;
        }
        let raw = take_bytes(&mapping, &mut o, tok_len, pack_path, "tokenizer")?;
        let tok = Tokenizer::from_bytes(raw).map_err(|e| {
            anyhow::anyhow!("the tokenizer of pack {} could not be read: {e}", pack_path.display())
        })?;
        // A pack whose table is smaller than the tokenizer's vocabulary
        // opens, installs and reports full coverage: embedding skips rows
        // that do not exist, and if all of them are missing it produces only
        // null vectors with no sign anything is wrong. The `continue` while
        // embedding is the right net against a panic and stays where it is;
        // the inconsistency is caught here, once, while it is still possible
        // to name the file at fault.
        //
        // The count to compare against is the **model's** vocabulary, which
        // is exactly what the generator dumps into the table:
        // `construir_paquete.py` writes one row per piece of `model.vocab`
        // and leaves `added_tokens` untouched. With `true` the count would
        // be the union with `added_tokens`, which can carry ids outside the
        // pruned vocabulary's range, and then this check would reject
        // perfectly healthy packs. An `added_token` without a row is covered
        // by the `continue` while embedding, which is where it belongs: a
        // special token without a row is normal; an incomplete table is
        // not.
        let pieces = tok.get_vocab_size(false);
        if n_tokens < pieces {
            bail!(
                "pack {} declares {n_tokens} rows but its tokenizer has {pieces} \
                 pieces: the table is incomplete and the pack would produce null vectors",
                pack_path.display()
            );
        }
        let scales = f32s_en(&mapping, &mut o, dims, pack_path, "scales")?;
        let mins = f32s_en(&mapping, &mut o, dims, pack_path, "minimums")?;
        let table_size = n_tokens.checked_mul(dims).with_context(|| {
            format!("pack {} declares a table that is too large", pack_path.display())
        })?;
        let table_start = o;
        let fin_tabla = o.checked_add(table_size).with_context(|| {
            format!("pack {} declares a table that is too large", pack_path.display())
        })?;
        if mapping.len() < fin_tabla {
            bail!("the table of pack {} is truncated", pack_path.display());
        }
        Ok(Pack { mapping, tok, name, dims, n_tokens, scales, mins, table_start })
    }

    pub fn name(&self) -> &str {
        &self.name
    }

    pub fn dims(&self) -> usize {
        self.dims
    }

    /// The average of the rows for the text's tokens, normalized. Text with
    /// no tokens returns the null vector instead of failing: it is a
    /// legitimate input (a chunk of nothing but whitespace), not an error.
    pub fn embed(&self, text: &str) -> Result<Vec<f32>> {
        let enc = self
            .tok
            .encode(text, false)
            .map_err(|e| anyhow::anyhow!("could not tokenize: {e}"))?;
        let mut v = vec![0f32; self.dims];
        let mut used = 0usize;
        for &id in enc.get_ids() {
            let i = id as usize;
            if i >= self.n_tokens {
                continue;
            }
            let a = self.table_start + i * self.dims;
            let row = &self.mapping[a..a + self.dims];
            for d in 0..self.dims {
                v[d] += row[d] as f32 * self.scales[d] + self.mins[d];
            }
            used += 1;
        }
        if used == 0 {
            return Ok(v);
        }
        let k = used as f32;
        let mut norma = 0f32;
        for d in 0..self.dims {
            v[d] /= k;
            norma += v[d] * v[d];
        }
        let norma = norma.sqrt();
        if norma > 1e-9 {
            for d in 0..self.dims {
                v[d] /= norma;
            }
        }
        Ok(v)
    }
}

/// sha256 of the whole file, in lowercase hexadecimal.
pub fn sha256(pack_path: &Path) -> Result<String> {
    let mut f = std::fs::File::open(pack_path)
        .with_context(|| format!("could not open {}", pack_path.display()))?;
    let mut h = Sha256::new();
    std::io::copy(&mut f, &mut h)?;
    Ok(format!("{:x}", h.finalize()))
}
